    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    # identify solid boundary rows or columns; use the two full-color lines
    full=[]
    for r,row in enumerate(grid):
        if len(set(row))==1 and row[0]!=0: full.append(('r',r,row[0]))
    for c in range(w):
        vals=[grid[r][c] for r in range(h)]
        if len(set(vals))==1 and vals[0]!=0: full.append(('c',c,vals[0]))
    if len(full)>=2 and full[0][0]=='r' and full[1][0]=='r':
        a,b=sorted(full[:2],key=lambda x:x[1]); lo,hi=a[1],b[1]
        for r in range(h):
            for c in range(w):
                if grid[r][c]==1:
                    # nearest boundary, ties toward first/top
                    if r-lo <= hi-r:
                        if r>lo: out[r-1][c]=a[2]
                    else:
                        if r<hi: out[r+1][c]=b[2]
